import{_ as a,o as t,c as r,al as l}from"./chunks/framework.BawR2jEz.js";const g=JSON.parse('{"title":"API телеграм","description":"Боты и сотрудники, которым exDoc отправляет уведомления в Telegram — из форм на сайте и из событий.","frontmatter":{"title":"API телеграм","description":"Боты и сотрудники, которым exDoc отправляет уведомления в Telegram — из форм на сайте и из событий."},"headers":[],"relativePath":"settings/api-telegram.md","filePath":"settings/api-telegram.md"}'),i={name:"settings/api-telegram.md"};function o(s,e,n,h,c,d){return t(),r("div",null,[...e[0]||(e[0]=[l('<h1 id="api-телеграм" tabindex="-1">API телеграм <a class="header-anchor" href="#api-телеграм" aria-label="Permalink to &quot;API телеграм&quot;">​</a></h1><p>Здесь формируется список ботов и сотрудников, которым exDoc пишет в Telegram. Этот список потом используют двое: <a href="./../fields/form/">поле «Форма»</a> — уведомление уходит после отправки формы на сайте, и <a href="./api-telegram-events.html">события</a> — уведомление отправляет код.</p><h2 id="добавление-бота" tabindex="-1">Добавление бота <a class="header-anchor" href="#добавление-бота" aria-label="Permalink to &quot;Добавление бота&quot;">​</a></h2><ol><li>Создайте бота через <a href="https://t.me/BotFather" target="_blank" rel="noreferrer">@BotFather</a> в Telegram</li><li>Скопируйте полученный API-токен</li><li>В настройках exDoc добавьте нового бота: укажите <strong>Название бота</strong> — оно нужно только вам, чтобы отличать боты в списке, — и вставьте токен</li><li>Сохраните настройки</li></ol><h2 id="добавление-сотрудника" tabindex="-1">Добавление сотрудника <a class="header-anchor" href="#добавление-сотрудника" aria-label="Permalink to &quot;Добавление сотрудника&quot;">​</a></h2><p>После добавления API-токена бота необходимо узнать <code>user_id</code> каждого сотрудника, который будет получать уведомления.</p><ol><li>Попросите сотрудника написать любое сообщение в добавленного бота в Telegram</li><li>В настройках exDoc нажмите кнопку <strong>Проверить обновления</strong> — откроется попап-окно с логами переписки бота</li><li>В логах найдите <code>user_id</code> сотрудника</li><li>Нажмите <strong>Добавить сотрудника</strong></li><li>Укажите: <ul><li><strong>Имя</strong> — для внутреннего использования (например, «Иван — менеджер»)</li><li><strong>User ID</strong> — числовой идентификатор из логов</li></ul></li></ol><p>Повторите для каждого сотрудника, который должен получать уведомления.</p><h2 id="см-также" tabindex="-1">См. также <a class="header-anchor" href="#см-также" aria-label="Permalink to &quot;См. также&quot;">​</a></h2><ul><li><a href="./api-telegram-events.html">События API Telegram Bot</a> — уведомления, которые вызываются из кода</li><li><a href="./">Настройки</a> — остальные вкладки раздела</li></ul>',10)])])}const p=a(i,[["render",o]]);export{g as __pageData,p as default};
